import { test, expect } from '@playwright/test';

test.describe('Card Decline Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/payment');
  });

  test('should display error message when card is declined', async ({ page }) => {
    // Locate and fill card number input using getByLabel
    const cardNumberInput = page.getByLabel('Card Number');
    await cardNumberInput.fill('4111111111111111');

    // Locate and fill expiry date input using getByLabel
    const expiryDateInput = page.getByLabel('Expiry Date');
    await expiryDateInput.fill('12/25');

    // Locate and fill CVV input using getByLabel
    const cvvInput = page.getByLabel('CVV');
    await cvvInput.fill('123');

    // Locate and click submit button using getByRole
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Wait for error message to appear
    await page.waitForTimeout(500);

    // Verify error message is visible using getByRole
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('Card declined');

    // Verify error message contains specific decline reason
    await expect(errorMessage).toContainText('Please try another card');

    // Verify payment form is still visible
    const paymentForm = page.locator('[data-testid="payment-form"]');
    await expect(paymentForm).toBeVisible();
  });

  test('should allow user to retry payment after card decline', async ({ page }) => {
    // Locate and fill card number input using getByLabel
    const cardNumberInput = page.getByLabel('Card Number');
    await cardNumberInput.fill('4111111111111111');

    // Locate and fill expiry date input using getByLabel
    const expiryDateInput = page.getByLabel('Expiry Date');
    await expiryDateInput.fill('12/25');

    // Locate and fill CVV input using getByLabel
    const cvvInput = page.getByLabel('CVV');
    await cvvInput.fill('123');

    // Locate and click submit button using getByRole
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify error message appears
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('Card declined');

    // Locate and clear card number input using getByLabel
    await cardNumberInput.clear();

    // Locate and fill with valid card number
    await cardNumberInput.fill('4211111111111111');

    // Locate and fill expiry date input using getByLabel
    await expiryDateInput.fill('01/26');

    // Locate and fill CVV input using getByLabel
    await cvvInput.fill('412');

    // Locate and click submit button again using getByRole
    await submitButton.click();

    // Verify success message appears
    const successMessage = page.getByRole('status');
    await expect(successMessage).toBeVisible();
    await expect(successMessage).toContainText('Payment successful');

    // Verify error message is no longer visible
    await expect(errorMessage).not.toBeVisible();
  });
});
